    // Inlined favicon SVGs (no Wikimedia hotlinking / HTTP 429). Credit: StonedKhajiit
    // Real 1999-2008 google.com favicon (16x16 .ico, from the Wayback Machine)
    const UGF_FAVICON_1999 = "data:image/x-icon;base64,";
    // Real 2009-early 2010 google.com favicon (16x16 .ico, lowercase blue g)
    const UGF_FAVICON_2009_G = "data:image/x-icon;base64,";
    // Real 2010-2012 google.com favicon (16x16 .ico, white g on the four-colour tile)
    const UGF_FAVICON_2010 = "data:image/x-icon;base64,";
    // Real late 2012 - Sep 2015 google.com favicon (.ico with 16x16 and 32x32, white g on blue)
    const UGF_FAVICON_2012 = "data:image/x-icon;base64,";
    // Real Sep 2015 - 2024 google.com favicon (.ico with 16x16 and 32x32, four-colour G)
    const UGF_FAVICON_2015 = "data:image/x-icon;base64,";
    function ugfFaviconForLayout() {
        const h = document.querySelector("html");
        const era = ugfRetroEra();
        // 2009/2010 eras used the multicolour tile; 1997-2008 used the blue G with coloured edges
        if (era === "gplex2009") {
            return UGF_FAVICON_2009_G;
        }
        if (era === "gplex2010") {
            return UGF_FAVICON_2010;
        }
        if (era && era !== "gplex2022") {
            return UGF_FAVICON_1999;
        }
        if (era === "gplex2022") {
            return UGF_FAVICON_2015;
        }
        const layout = h.getAttribute("layout") || "";
        if (["2010", "2011", "2012"].indexOf(layout) > -1) {
            return UGF_FAVICON_2010;
        }
        if (["2013", "2013L", "2014", "2015", "2015L"].indexOf(layout) > -1) {
            return UGF_FAVICON_2012;
        }
        if (["2016", "2016C", "2016L", "2017", "2018", "2018M", "2019"].indexOf(layout) > -1) {
            return UGF_FAVICON_2015;
        }
        if (layout === "retro") {
            return UGF_FAVICON_1999;
        }
        return null;
    }
    let ugfFaviconObserver = null;
    function ugfApplyFavicon(href) {
        document.querySelectorAll("link[rel~='icon'], link[rel='shortcut icon'], link[rel='apple-touch-icon'], link[rel='mask-icon']").forEach(function(el) {
            if (el.id !== "ugf-favicon" && el.parentElement) {
                el.parentElement.removeChild(el);
            }
        });
        let link = document.querySelector("#ugf-favicon");
        if (!link) {
            link = document.createElement("link");
            link.id = "ugf-favicon";
            link.setAttribute("rel", "icon");
            link.setAttribute("type", "image/svg+xml");
        }
        const type = href.indexOf("data:image/x-icon") === 0 ? "image/x-icon" : (href.indexOf("data:image/png") === 0 ? "image/png" : "image/svg+xml");
        if (link.getAttribute("type") !== type) {
            link.setAttribute("type", type);
        }
        if (link.getAttribute("href") !== href) {
            link.setAttribute("href", href);
        }
        const head = document.head || document.documentElement;
        if (link.parentElement !== head || head.lastElementChild !== link) {
            head.appendChild(link);
        }
    }
    function ugfSetFavicon() {
        if (document.querySelector("html").hasAttribute("disabled")) {
            return;
        }
        const href = ugfFaviconForLayout();
        if (!href) {
            return;
        }
        ugfApplyFavicon(href);
        if (ugfFaviconObserver) {
            ugfFaviconObserver.disconnect();
        }
        // Google re-inserts its own favicon link after we run, so hold ours in place
        ugfFaviconObserver = new MutationObserver(function(muts) {
            for (let i = 0; i < muts.length; i++) {
                const added = muts[i].addedNodes;
                for (let j = 0; j < added.length; j++) {
                    const n = added[j];
                    if (n.nodeType === 1 && n.tagName === "LINK" && (n.getAttribute("rel") || "").indexOf("icon") > -1 && n.id !== "ugf-favicon") {
                        ugfApplyFavicon(href);
                        return;
                    }
                }
            }
        });
        ugfFaviconObserver.observe(document.head || document.documentElement, { childList: true, subtree: true });
        let ticks = 0;
        const iv = setInterval(function() {
            ugfApplyFavicon(href);
            if (++ticks > 20) {
                clearInterval(iv);
            }
        }, 500);
    }
    function ugfSetEraLayout(storeKey, baseLayout, attr) {
        const h = document.querySelector("html");
        ["gplex1997", "gplex1998", "gplex1999", "gplex2000", "gplex2001", "gplex2002", "gplex2003", "gplex2005", "gplex2006", "gplex2007", "gplex2009", "gplex2010", "gplex2022"].forEach(function(a) {
            h.removeAttribute(a);
        });
        h.setAttribute("layout", baseLayout);
        if (attr) {
            h.setAttribute(attr, "");
        }
        localStorage.setItem("UGF_LAYOUT", storeKey);
        ugfSetFavicon();
        if (attr && attr !== "gplex2022") {
            h.setAttribute("legacy-gbar", "");
            h.setAttribute("legacy-images", "");
            h.setAttribute("legacy-footer", "");
        }
    }
